-- Resources content for the Schedule section and the hours closed to
-- underwriting (CLAUDE.md, "Resources stay in step with the code"). Content
-- only; the schema change is 20261005130000. Programs, Automation and the new
-- Underwriting page sit under one Schedule tab, so the Automation guide
-- (released as its own tab in 20261005120000) and the Programs guide are
-- updated with the new way in, and the Programs guide with the shading.

select private.rc_release_guide(
  p_slug => 'log-underwriting-hours',
  p_tool_key => 'log',
  p_title => 'Underwriting hours',
  p_summary => 'Which hours are closed to underwriting auto-fill: weekly closed windows and one-time changes.',
  p_screen_keys => array['log.underwriting-hours'],
  p_sort_order => 46,
  p_version_note => 'Underwriting hours',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-fill may schedule an underwriting credit in any hour unless it's closed on this page. Open it from "},{"type":"text","text":"Schedule","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Underwriting","marks":[{"type":"bold"}]},{"type":"text","text":". Traffic staff can still place a credit by hand in a closed hour, and hosts can still move one; the rule reaches automation only."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Closed every week"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ Weekly hours","marks":[{"type":"bold"}]},{"type":"text","text":" for the routine ones, such as 5:00 AM to 5:00 PM every day. Pick the days, the times, and the date they start."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Programs in these hours","marks":[{"type":"bold"}]},{"type":"text","text":" column shows what's on the air while credits are closed."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"One-time changes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ One-time change","marks":[{"type":"bold"}]},{"type":"text","text":" for a pledge drive or a special. Choose "},{"type":"text","text":"Closed","marks":[{"type":"bold"}]},{"type":"text","text":" to close hours that are normally open, or "},{"type":"text","text":"Open","marks":[{"type":"bold"}]},{"type":"text","text":" to open hours that are normally closed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A one-time change wins over the weekly hours. One-time changes can't overlap each other."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Midnight to midnight covers whole days: a pledge week is Monday 12:00 AM until the next Monday 12:00 AM."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Week and month"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The week view draws each day's closed hours over the programs on the air, with the automated hours shown faintly behind them. Hatched red is closed every week, dashed hatched is closed once, and dashed green is open once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The month view shows each day's closed hours. Pick a day to see its week."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Programs week view shades the same hours behind the programs."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-fill never places a credit in a closed hour, never moves one there, and never generates a rundown for a day whose eligible breaks are all closed. Traffic's dashboard names a line whose upcoming period falls entirely in closed hours."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A credit already placed stays where it is when the hours change."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only the program director can change these hours. Nothing is deleted: removing hours or a change takes it off the schedule."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-automated-hours',
  p_tool_key => 'log',
  p_title => 'Automation',
  p_summary => 'When no one is in the studio: weekly automated hours and one-time changes, and what they mean for credits.',
  p_screen_keys => array['log.automated-hours'],
  p_sort_order => 45,
  p_version_note => 'Under the Schedule tab, beside Underwriting hours',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every hour is hosted unless it's listed on this page. In automated hours no one is in the studio, so DAD plays that hour's underwriting credits. Open it from "},{"type":"text","text":"Schedule","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Automation","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weekly hours"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ Weekly hours","marks":[{"type":"bold"}]},{"type":"text","text":" for the routine ones, such as overnights from 8:00 PM to 5:00 AM. Pick the days, the times, and the date they start."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started, so Saturday 8:00 PM – 5:00 AM covers early Sunday."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Weekly hours can cover a whole program or just some of its hours. The "},{"type":"text","text":"Programs in these hours","marks":[{"type":"bold"}]},{"type":"text","text":" column shows what's on the air then."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"One-time changes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ One-time change","marks":[{"type":"bold"}]},{"type":"text","text":" for a holiday, a host out, or a special. Choose "},{"type":"text","text":"Automated","marks":[{"type":"bold"}]},{"type":"text","text":" to automate hours that are normally hosted, or "},{"type":"text","text":"Live","marks":[{"type":"bold"}]},{"type":"text","text":" to host hours that are normally automated."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A one-time change wins over the weekly hours. One-time changes can't overlap each other."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Midnight to midnight covers whole days: Thanksgiving is Thursday 12:00 AM until Friday 12:00 AM."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Week and month"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The week view draws each day's automated hours over the programs on the air, with the hours closed to underwriting shown faintly behind them. Grey is weekly, dashed amber is automated once, and dashed blue is live once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The month view shows each day's automated hours. Pick a day to see its week."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A credit in automated hours needs copy with a DAD cut, since DAD plays it. A live read qualifies through its recorded version. Auto-fill leaves those breaks to copy that has one, and placing cut-less copy there is refused."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only the program director can change automated hours. Nothing is deleted: removing hours or a change takes it off the schedule."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-schedule-a-program',
  p_tool_key => 'log',
  p_title => 'Schedule a program',
  p_summary => 'See the week, change when a program airs, and find programs that still need a clock.',
  p_screen_keys => array['log.program', 'log.program.schedule'],
  p_sort_order => 20,
  p_version_note => 'The Schedule tab, and shaded automated and closed hours',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Schedule","marks":[{"type":"bold"}]},{"type":"text","text":" tab is where the schedule and every clock are reached from. Its row of pages is "},{"type":"text","text":"Programs","marks":[{"type":"bold"}]},{"type":"text","text":" (what airs when), "},{"type":"text","text":"Automation","marks":[{"type":"bold"}]},{"type":"text","text":" (when no one is in the studio), and "},{"type":"text","text":"Underwriting","marks":[{"type":"bold"}]},{"type":"text","text":" (hours closed to underwriting credits). Scheduling and changing a clock are the program director's tasks."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"See the schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Week","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the week as a grid, one column per day, with each program at its air time and the clock it runs on. Behind the programs, grey shading is the automated hours and red hatching is the hours closed to underwriting, each edited on its own page. Programs still on the shared placeholder clock are shaded amber. Select a block to see its details, then "},{"type":"text","text":"Edit schedule","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Open program","marks":[{"type":"bold"}]},{"type":"text","text":". Use Prev, Next, and Today to change the week. The "},{"type":"text","text":"List","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the same programs as a table."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find what needs attention"}]},{"type":"paragraph","content":[{"type":"text","text":"In the list, "},{"type":"text","text":"Needs a clock","marks":[{"type":"bold"}]},{"type":"text","text":" shows the programs still on the placeholder clock, and "},{"type":"text","text":"Not scheduled","marks":[{"type":"bold"}]},{"type":"text","text":" shows programs with no current schedule. Clocks no program uses are listed under "},{"type":"text","text":"Unused clocks","marks":[{"type":"bold"}]},{"type":"text","text":" below the list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change when a program airs"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the program. Under "},{"type":"text","text":"When it airs","marks":[{"type":"bold"}]},{"type":"text","text":" each schedule shows its days and time; select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":". The clock it runs on is changed in the same editor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose the days, the start time, and the length. The quick buttons set weekdays, the weekend, or every day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set when the schedule starts and, if it stops, when it ends. Pick the clock it runs on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the preview on the right. It shows the times, the next airing, and whether another program airs at the same time on those days. An overlap is a warning; it doesn't stop you saving."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Save schedule","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Rundowns that were already generated keep the clock they were built from; a new clock applies to rundowns generated from then on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"+ Add a time","marks":[{"type":"bold"}]},{"type":"text","text":" on a program's page, choose its days, time, and clock, and save. If the clock doesn't exist yet, select "},{"type":"text","text":"Create a clock for this program","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a program's details"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Details","marks":[{"type":"bold"}]},{"type":"text","text":" panel on a program's page holds its name, kind, description, and NPR connection. The program director selects "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on the panel to change them in place, then "},{"type":"text","text":"Save changes","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Collection ID","marks":[{"type":"bold"}]},{"type":"text","text":" is NPR's ID for the program. With it set, On Air reads that day's NPR stories for the program's rundowns. Leave it blank to stop reading NPR for the program."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feed's first hour (Eastern)","marks":[{"type":"bold"}]},{"type":"text","text":" only matters for NPR's multi-hour shows, whose hours alternate on the feed. It lines up NPR's hours with ours so estimated story times are right. Leave it on "},{"type":"text","text":"Same as our schedule","marks":[{"type":"bold"}]},{"type":"text","text":" unless NPR's first hour differs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changing the collection ID clears the program's saved NPR stories from today on, so the next look fetches the new ones. Earlier dates keep what they had."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-05-log-schedule-and-underwriting-hours',
  p_tool_key => 'log',
  p_released_on => '2026-10-05',
  p_title => 'A Schedule tab, and hours closed to underwriting',
  p_guide_slugs => array['log-underwriting-hours', 'log-automated-hours', 'log-schedule-a-program'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On Air's Programs tab is now Schedule, with three pages in a row: Programs, Automation, and a new Underwriting page listing the hours closed to underwriting credits. Auto-fill never schedules a credit in a closed hour, moves one there, or generates a rundown for a day whose eligible breaks are all closed; placing a credit by hand is still allowed. The Programs week view shades both the automated hours and the closed hours behind the programs."}]}]}$body$
);
